#include "dlss/object_motion.h"

#include <wrl/client.h>

#include <algorithm>
#include <atomic>
#include <cstring>
#include <mutex>

#include "camera/scene_camera.h"
#include "common/log.h"
#include "common/pointer_set.h"
#include "object_motion_ps.h"  // generated by fxc: kObjectMotionPs

using Microsoft::WRL::ComPtr;

namespace ds3::object_motion {
namespace {

// Slots our pixel shader uses; the game's values there are saved and restored.
constexpr UINT kDepthSlot = 20;
constexpr UINT kCbSlot = 13;

// Velocity vertex shaders seen in DS3 1.15.2 frame dumps. Others are found by
// the names in their reflection data (see OnVertexShaderCreated).
constexpr uint64_t kKnownVelocityVs[] = {0xC48361A10D38D8D5ull, 0x96632548D75B4C2Full,
                                         0xF54DC44863BE505Aull, 0x3E098128A8A5C75Aull};

// The motion blur itself: two full-screen draws that blur the post-process
// scene in place (T760 -> T768 -> T760). Skipped when HideMotionBlur is on.
constexpr uint64_t kMotionBlurPs = 0xE484BFEBC00C5CF7ull;

PointerSet<16384> g_velocity_vs;
PointerSet<1024> g_blur_ps;
std::atomic<uint32_t> g_velocity_vs_count{0};

// What each context currently has bound. A context is only used by one thread
// at a time, so its slot needs no further locking.
struct ContextSlot {
  std::atomic<ID3D11DeviceContext*> ctx{nullptr};
  std::atomic<bool> velocity{false};  // a velocity vertex shader
  std::atomic<bool> blur{false};      // the motion blur pixel shader
};
constexpr size_t kMaxContexts = 64;
ContextSlot g_contexts[kMaxContexts];

std::atomic<bool> g_active{false};
std::atomic<bool> g_hide_blur{false};
std::atomic<bool> g_ready{false};
std::atomic<uint32_t> g_redraws{0};

struct alignas(16) PsParams {
  float proj_z;
  float pad[3];
};

// Written on the immediate context's thread, read by any recording thread.
std::mutex g_mutex;
struct Resources {
  UINT w = 0, h = 0;
  ComPtr<ID3D11PixelShader> ps;
  ComPtr<ID3D11Buffer> cb;
  float proj_z = 0.0f;
  ComPtr<ID3D11Texture2D> target;
  ComPtr<ID3D11RenderTargetView> rtv;
  ComPtr<ID3D11ShaderResourceView> srv;
  ID3D11Texture2D* depth_source = nullptr;  // identity only
  ComPtr<ID3D11ShaderResourceView> depth_srv;
} g_res;

ContextSlot* FindSlot(ID3D11DeviceContext* ctx, bool create) {
  for (ContextSlot& s : g_contexts) {
    ID3D11DeviceContext* owner = s.ctx.load(std::memory_order_acquire);
    if (owner == ctx) return &s;
    if (!owner) {
      if (!create) return nullptr;
      if (s.ctx.compare_exchange_strong(owner, ctx)) return &s;
      if (owner == ctx) return &s;
    }
  }
  return nullptr;
}

}  // namespace

void OnVertexShaderCreated(ID3D11VertexShader* vs, const void* code, size_t length,
                           uint64_t hash) {
  if (!vs || !code) return;
  const bool known = std::find(std::begin(kKnownVelocityVs), std::end(kKnownVelocityVs), hash) !=
                     std::end(kKnownVelocityVs);
  // Velocity shaders transform with both the current and the previous object
  // matrices; no other pass needs cbPrevObjMatrix.
  const bool found = !known && BytecodeContains(code, length, "VC_PrevMatrixWVP") &&
                     BytecodeContains(code, length, "cbPrevObjMatrix");
  if (!known && !found) {
    g_velocity_vs.Erase(vs);  // a new shader at a released velocity shader's address
    return;
  }
  g_velocity_vs.Insert(vs);
  // The same shaders are created many times: log the first few, then the count now and then.
  const uint32_t n = ++g_velocity_vs_count;
  if (n <= 16 || (n & (n - 1)) == 0)
    Log("object motion: velocity VS %016llX (%s), %u so far", static_cast<unsigned long long>(hash),
        known ? "known" : "detected", n);
}

void OnPixelShaderCreated(ID3D11PixelShader* ps, uint64_t hash) {
  if (!ps) return;
  if (hash == kMotionBlurPs) {
    g_blur_ps.Insert(ps);
    Log("object motion: motion blur PS found");
  } else {
    g_blur_ps.Erase(ps);
  }
}

void OnSetVertexShader(ID3D11DeviceContext* ctx, ID3D11VertexShader* vs) {
  const bool velocity = g_velocity_vs.Contains(vs);
  ContextSlot* slot = FindSlot(ctx, velocity);
  if (slot) slot->velocity.store(velocity, std::memory_order_relaxed);
}

void OnSetPixelShader(ID3D11DeviceContext* ctx, ID3D11PixelShader* ps) {
  const bool blur = g_blur_ps.Contains(ps);
  ContextSlot* slot = FindSlot(ctx, blur);
  if (slot) slot->blur.store(blur, std::memory_order_relaxed);
}

bool SkipDraw(ID3D11DeviceContext* ctx) {
  if (!g_hide_blur.load(std::memory_order_relaxed)) return false;
  const ContextSlot* slot = FindSlot(ctx, false);
  return slot && slot->blur.load(std::memory_order_relaxed);
}

bool WantsRedraw(ID3D11DeviceContext* ctx) {
  if (!g_active.load(std::memory_order_relaxed) || !g_ready.load(std::memory_order_relaxed))
    return false;
  const ContextSlot* slot = FindSlot(ctx, false);
  return slot && slot->velocity.load(std::memory_order_relaxed);
}

bool Begin(ID3D11DeviceContext* ctx, SavedState* s) {
  ComPtr<ID3D11RenderTargetView> rtv;
  ComPtr<ID3D11ShaderResourceView> depth_srv;
  ComPtr<ID3D11Buffer> cb;
  ComPtr<ID3D11PixelShader> ps;
  UINT w, h;
  {
    std::lock_guard lock(g_mutex);
    rtv = g_res.rtv;
    depth_srv = g_res.depth_srv;
    cb = g_res.cb;
    ps = g_res.ps;
    w = g_res.w;
    h = g_res.h;
  }
  if (!rtv || !depth_srv || !cb || !ps) return false;

  ctx->OMGetRenderTargets(D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT, s->rtvs, &s->dsv);
  s->ps_instance_count = D3D11_SHADER_MAX_INTERFACES;
  ctx->PSGetShader(&s->ps, s->ps_instances, &s->ps_instance_count);
  ctx->PSGetShaderResources(kDepthSlot, 1, &s->srv);
  ctx->PSGetConstantBuffers(kCbSlot, 1, &s->cb);
  ctx->OMGetBlendState(&s->blend, s->blend_factor, &s->sample_mask);
  s->viewport_count = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
  ctx->RSGetViewports(&s->viewport_count, s->viewports);
  s->scissor_count = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
  ctx->RSGetScissorRects(&s->scissor_count, s->scissors);

  // No depth buffer: the pixel shader tests against the scene depth itself.
  ctx->OMSetRenderTargets(1, rtv.GetAddressOf(), nullptr);
  ctx->OMSetBlendState(nullptr, nullptr, 0xFFFFFFFF);
  ctx->PSSetShader(ps.Get(), nullptr, 0);
  ctx->PSSetShaderResources(kDepthSlot, 1, depth_srv.GetAddressOf());
  ctx->PSSetConstantBuffers(kCbSlot, 1, cb.GetAddressOf());
  // The velocity shaders are unjittered; shifting the viewport by this frame's
  // jitter puts each object's pixels exactly where the jittered scene has them
  // (the motion values come from the shaders' matrices and are unaffected).
  float ox = 0.0f, oy = 0.0f;
  if (!camera::CurrentJitter(&ox, &oy)) ox = oy = 0.0f;
  const D3D11_VIEWPORT viewport = {ox, oy, static_cast<float>(w), static_cast<float>(h),
                                   0.0f, 1.0f};
  ctx->RSSetViewports(1, &viewport);
  const D3D11_RECT scissor = {0, 0, static_cast<LONG>(w), static_cast<LONG>(h)};
  ctx->RSSetScissorRects(1, &scissor);
  g_redraws.fetch_add(1, std::memory_order_relaxed);
  return true;
}

void End(ID3D11DeviceContext* ctx, SavedState* s) {
  // Unbind the scene depth first, in case the game's depth buffer comes back as the DSV.
  ctx->PSSetShaderResources(kDepthSlot, 1, &s->srv);
  ctx->OMSetRenderTargets(D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT, s->rtvs, s->dsv);
  ctx->OMSetBlendState(s->blend, s->blend_factor, s->sample_mask);
  ctx->PSSetShader(s->ps, s->ps_instances, s->ps_instance_count);
  ctx->PSSetConstantBuffers(kCbSlot, 1, &s->cb);
  ctx->RSSetViewports(s->viewport_count, s->viewports);
  ctx->RSSetScissorRects(s->scissor_count, s->scissors);
  auto release = [](auto* p) {
    if (p) p->Release();
  };
  for (auto* p : s->rtvs) release(p);
  release(s->dsv);
  release(s->ps);
  for (UINT i = 0; i < s->ps_instance_count; ++i) release(s->ps_instances[i]);
  release(s->srv);
  release(s->cb);
  release(s->blend);
}

void SetActive(bool active, bool hide_motion_blur) {
  g_active.store(active, std::memory_order_relaxed);
  g_hide_blur.store(active && hide_motion_blur, std::memory_order_relaxed);
}

bool Prepare(ID3D11Device* device, ID3D11DeviceContext* ctx, UINT w, UINT h,
             ID3D11Texture2D* scene_depth, float proj_z) {
  std::lock_guard lock(g_mutex);
  HRESULT hr = S_OK;
  if (!g_res.ps) {
    hr = device->CreatePixelShader(kObjectMotionPs, sizeof(kObjectMotionPs), nullptr, &g_res.ps);
    if (SUCCEEDED(hr)) {
      D3D11_BUFFER_DESC d = {};
      d.ByteWidth = sizeof(PsParams);
      d.Usage = D3D11_USAGE_DEFAULT;
      d.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
      hr = device->CreateBuffer(&d, nullptr, &g_res.cb);
    }
    if (FAILED(hr)) {
      Log("object motion: shader setup failed: 0x%08X", hr);
      g_res.ps.Reset();
      return false;
    }
    g_res.proj_z = 0.0f;
  }
  if (g_res.w != w || g_res.h != h || !g_res.rtv) {
    g_ready = false;
    g_res.target.Reset();
    g_res.rtv.Reset();
    g_res.srv.Reset();
    D3D11_TEXTURE2D_DESC d = {};
    d.Width = w;
    d.Height = h;
    d.MipLevels = 1;
    d.ArraySize = 1;
    d.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
    d.SampleDesc.Count = 1;
    d.Usage = D3D11_USAGE_DEFAULT;
    d.BindFlags = D3D11_BIND_RENDER_TARGET | D3D11_BIND_SHADER_RESOURCE;
    hr = device->CreateTexture2D(&d, nullptr, &g_res.target);
    if (SUCCEEDED(hr)) hr = device->CreateRenderTargetView(g_res.target.Get(), nullptr, &g_res.rtv);
    if (SUCCEEDED(hr))
      hr = device->CreateShaderResourceView(g_res.target.Get(), nullptr, &g_res.srv);
    if (FAILED(hr)) {
      Log("object motion: creating the %ux%u target failed: 0x%08X", w, h, hr);
      g_res.target.Reset();
      g_res.rtv.Reset();
      g_res.srv.Reset();
      return false;
    }
    g_res.w = w;
    g_res.h = h;
    const FLOAT zero[4] = {};
    ctx->ClearRenderTargetView(g_res.rtv.Get(), zero);
    Log("object motion: target created for %ux%u", w, h);
  }
  if (g_res.depth_source != scene_depth) {
    g_res.depth_srv.Reset();
    g_res.depth_source = scene_depth;
    D3D11_TEXTURE2D_DESC dd;
    scene_depth->GetDesc(&dd);
    // A typed D32S8 texture cannot be read; only the typeless one DS3 uses can.
    if (dd.Format == DXGI_FORMAT_R32G8X24_TYPELESS && (dd.BindFlags & D3D11_BIND_SHADER_RESOURCE)) {
      D3D11_SHADER_RESOURCE_VIEW_DESC v = {};
      v.Format = DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS;
      v.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
      v.Texture2D.MipLevels = 1;
      hr = device->CreateShaderResourceView(scene_depth, &v, &g_res.depth_srv);
      if (FAILED(hr)) Log("object motion: scene depth view failed: 0x%08X", hr);
    } else {
      Log("object motion: scene depth (fmt %d, bind 0x%X) is not readable, disabled", dd.Format,
          dd.BindFlags);
    }
  }
  if (g_res.proj_z != proj_z) {
    const PsParams p = {proj_z, {}};
    ctx->UpdateSubresource(g_res.cb.Get(), 0, nullptr, &p, 0, 0);
    g_res.proj_z = proj_z;
  }
  const bool ready = g_res.depth_srv != nullptr;
  g_ready = ready;
  return ready;
}

ID3D11ShaderResourceView* Srv() {
  std::lock_guard lock(g_mutex);
  return g_ready ? g_res.srv.Get() : nullptr;
}

void Clear(ID3D11DeviceContext* ctx) {
  std::lock_guard lock(g_mutex);
  if (!g_res.rtv) return;
  const FLOAT zero[4] = {};
  ctx->ClearRenderTargetView(g_res.rtv.Get(), zero);
}

uint32_t TakeRedrawCount() { return g_redraws.exchange(0, std::memory_order_relaxed); }

}  // namespace ds3::object_motion
